python -m pip install --upgrade pip
if ("${{ matrix.python }}" -eq "3.14") {
  python -m pip install --editable ".[mcp]"
} else {
  python -m pip install --editable .
}

$failed = $false
Get-ChildItem scripts/ci/windows, examples -Filter *.ps1 | ForEach-Object {
  $tokens = $null
  $errors = $null
  [Management.Automation.Language.Parser]::ParseFile(
    $_.FullName,
    [ref]$tokens,
    [ref]$errors
  ) | Out-Null
  if ($errors.Count -gt 0) {
    $failed = $true
    $errors | ForEach-Object {
      Write-Error "$($_.Extent.File):$($_.Extent.StartLineNumber): $($_.Message)"
    }
  }
}
if ($failed) { throw "PowerShell parser rejected one or more Windows CI scripts" }

swcli version --json
if ($LASTEXITCODE -ne 0) { throw "SWCLI entry point failed" }
python scripts/ci/verify-installed.py

if ([string]::IsNullOrWhiteSpace($env:RCLONE_CONFIG_B64)) {
  throw "Missing secret: RCLONE_CONFIG_B64"
}
New-Item -ItemType Directory -Force -Path $env:PROBE_ROOT | Out-Null
[IO.File]::WriteAllBytes($env:RCLONE_CONFIG_FILE, [Convert]::FromBase64String($env:RCLONE_CONFIG_B64))
if (-not (rclone --config $env:RCLONE_CONFIG_FILE listremotes | Select-String -SimpleMatch "gdrive:" -Quiet)) {
  throw "gdrive: remote is unavailable"
}

$wheels = @(Get-ChildItem -LiteralPath "$env:RUNNER_TEMP\swcli-dist" -Filter *.whl -File)
if ($wheels.Count -ne 1) { throw "Expected exactly one SWCLI wheel from the package job" }
python --version
python -m pip install --upgrade pip
if ($LASTEXITCODE -ne 0) { throw "pip upgrade failed" }
python -m pip install $wheels[0].FullName
